    "självrättning": true,
    "miniräknare": true,
    "geogebra": false,
    "ledtrad": "<p>Bestäm först normalkraften. Använd sedan \\(F_f=\\mu N\\) och jämför krafterna längs rörelseriktningen.</p>",
    "kallaImport": "Fysik 1 - Friktion IX.docx #5",
    "svarFormat": "numeriskt",
    "svarEnhet": "N"
