    "tolerans": 0.041999999999999996,
    "självrättning": true,
    "miniräknare": true,
    "geogebra": false,
    "ledtrad": "<p>Börja med \\(p=F/A\\). Om trycket verkar på båda sidor är det tryckskillnaden som ger nettokraften.</p>",
    "kallaImport": "Fysik 1 - Tryck V.docx #5",
    "svarFormat": "numeriskt",
    "svarEnhet": "m"
