    "rättSvar": null,
    "tolerans": null,
    "självrättning": false,
    "familjNyckelTidigare": "potential__elektrisk_potentialenergi_och_spanning",
    "ledtrad": "<p>Tillfört \\(0{,}660\\ \\mathrm W\\). Resistorernas summan är \\(150(0{,}040)^2+150(0{,}020)^2+0{,}360=0{,}660\\ \\mathrm W\\).</p>"
