    "geogebra": false,
    "ledtrad": "<p>Koppla halveringstid till exponentiell minskning. Efter varje halveringstid återstår hälften av den tidigare mängden.</p>",
    "kallaImport": "Fysik 1 - Kol-14-metoden II.docx #2",
    "svarFormat": "numeriskt",
    "svarEnhet": null
