    "miniräknare": true,
    "geogebra": false,
    "ledtrad": "<p>Enheten på lutningen blir kg/m³ eftersom massan står i kg och volymen i m³.</p>",
    "svarFormat": "numeriskt",
    "svarEnhet": "kg/m³",
    "spel": false
